Item.method_code:
/*
    現在のアクティビティから引き戻しパスを非表示する
    ※承認依頼から作業中への引き戻し用
*/
Innovator inn = this.getInnovator();
const string targetPathName = "pullBack_RA_IP";

//thisからActivityのidを取得
string id = this.getProperty("id");

string body = "<targetPathName>"+targetPathName+"</targetPathName><acId>"+id+"</acId>";
var retItem = inn.applyMethod("h4_hidePath",body);
if(retItem.isError())
{
    //エラー
    return inn.newError(retItem.getErrorString());
}
return this;
